import json

# Search for GDP in the JSON structure
data = json.load(open('/app/resources/treasury_bulletin_2013_06.json'))

def search_for_value(obj, path=''):
    if isinstance(obj, dict):
        for key, value in obj.items():
            search_for_value(value, f'{path}.{key}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_for_value(item, f'{path}[{i}]')
    elif isinstance(obj, str):
        if 'gdp' in obj.lower() or 'gross domestic' in obj.lower():
            print(f'{path}: {obj[:200]}')

search_for_value(data)
